const NS = "http://www.portalfiscal.inf.br/nfe/wsdl/NFeRetAutorizacao4";
const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function consultarRecibo(nRec: string, tentativas = 8): Promise<string> {
  const corpo =
    `<consReciNFe versao="4.00" xmlns="http://www.portalfiscal.inf.br/nfe">` +
    `<tpAmb>${TP_AMB}</tpAmb><nRec>${nRec}</nRec></consReciNFe>`;
  await espera(15000); // espera minima exigida pelo MOC
  let xml = "";
  for (let i = 0; i < tentativas; i++) {
    xml = await chamar("/ws/NfeRetAutorizacao/NFeRetAutorizacao4.asmx", "4.00", corpo, NS);
    if (!xml.includes("<cStat>105</cStat>")) return xml;
    await espera(Math.min(5000 * (i + 1), 30000));
  }
  return xml;
}

consultarRecibo("431000000000001").then(console.log).catch(console.error);

