const NS = "http://www.portalfiscal.inf.br/nfe/wsdl/NFeDistribuicaoDFe";
const CNPJ = "00000000000191";

// reaproveite chamar() trocando HOST por HOST_AN
async function* varrer(ultNSU = "000000000000000", limitePaginas = 200) {
  for (let i = 0; i < limitePaginas; i++) {
    const corpo =
      `<distDFeInt versao="1.01" xmlns="http://www.portalfiscal.inf.br/nfe">` +
      `<tpAmb>1</tpAmb><cUFAutor>${CUF}</cUFAutor><CNPJ>${CNPJ}</CNPJ>` +
      `<distNSU><ultNSU>${ultNSU}</ultNSU></distNSU></distDFeInt>`;
    const xml = await chamar("/NFeDistribuicaoDFe/NFeDistribuicaoDFe.asmx", "1.01", corpo, NS);
    for (const m of xml.matchAll(/<docZip[^>]*>([^<]+)<\/docZip>/g))
      yield zlib.gunzipSync(Buffer.from(m[1], "base64")).toString("utf-8");
    const ult = xml.match(/<ultNSU>(\d+)<\/ultNSU>/)?.[1];
    const max = xml.match(/<maxNSU>(\d+)<\/maxNSU>/)?.[1];
    if (!ult || !max) break;
    ultNSU = ult;                      // persista este cursor entre execucoes
    if (BigInt(ult) >= BigInt(max)) break;
  }
}

(async () => { for await (const doc of varrer()) console.log(doc.slice(0, 200)); })();

// Node 18+. fetch nativo nao envia certificado cliente: use https.request.
import * as https from "node:https";
import * as fs from "node:fs";

const CERT = fs.readFileSync("<<CAMINHO_CERT_PEM>>");
const KEY = fs.readFileSync("<<CAMINHO_CHAVE_PEM>>");
const HOST = "nfe-homologacao.svrs.rs.gov.br";   // homologacao SVRS, modelo 55
const CUF = "43";
const TP_AMB = "2";

function chamar(caminho: string, versaoDados: string, xmlInterno: string, nsWsdl: string): Promise<string> {
  const envelope =
    `<?xml version="1.0" encoding="utf-8"?>` +
    `<soap12:Envelope xmlns:soap12="http://www.w3.org/2003/05/soap-envelope">` +
    `<soap12:Header><nfeCabecMsg xmlns="${nsWsdl}">` +
    `<cUF>${CUF}</cUF><versaoDados>${versaoDados}</versaoDados>` +
    `</nfeCabecMsg></soap12:Header>` +
    `<soap12:Body><nfeDadosMsg xmlns="${nsWsdl}">${xmlInterno}</nfeDadosMsg></soap12:Body>` +
    `</soap12:Envelope>`;

  return new Promise((resolve, reject) => {
    const req = https.request(
      { host: HOST, path: caminho, method: "POST", cert: CERT, key: KEY, minVersion: "TLSv1.2",
        headers: { "Content-Type": "application/soap+xml; charset=utf-8" } },
      (res) => { let b = ""; res.on("data", (c) => (b += c)); res.on("end", () => resolve(b)); }
    );
    req.on("error", reject);
    req.end(envelope);
  });
}

const HOST_CAD = "cad.svrs.rs.gov.br";
