    `<ConsCad versao="2.00" xmlns="http://www.portalfiscal.inf.br/nfe">` +
    `<infCons><xServ>CONS-CAD</xServ><UF>${uf}</UF><CNPJ>${cnpj}</CNPJ></infCons></ConsCad>`;
  return chamar("/ws/cadconsultacadastro/cadconsultacadastro4.asmx", "2.00", corpo, NS);
}

